var ZelosAwardModal = new Class({

  debug: false,

  Implements: [Options, Events],

  Binds: [
    'set',
    'render',
    'close',
    '_retuirnApiFromRow', '_returnEmployeeNoFromRow', '_returnEmployeeNameFromRow', '_returnDateFromRow',
    '_isRowGood',
    '_getAwards', '_gotAwards',
    '_setPosition',
    '_startDrag', '_drag', '_stopDrag', '_clearDragEvents',
    '_closed'
  ],

  options: {
    row: false,
    user: '',
    date: '',
    iconData: [],
    returnRowMethod: false,
    isDraggable: true,
    startPosition: { // x or y = false means auto position center top
      x: false,
      y: false
    },
    isOpen: false
  },

  initialize: function (options)
  {
    if (!Affinity.isAwardsPopupEnabled()) return false;

    this.setOptions(options);

    if (!Affinity.hasOwnProperty('AwardModels'))
    {
      Affinity.AwardModels = {
        Widgets: [],
        closeAll: function ()
        {
          Affinity.AwardModels.Widgets.forEach(function (widget)
          {
            if (widget && widget.hasOwnProperty('close') && typeof widget.close === 'function')
            {
              widget.close();
            }
          });
        }
      };
    }

    Affinity.AwardModels.Widgets.push(this);

    var initHtml = '';
    initHtml += '<h2>Timesheet Information</h2>';

    this.baseLang = Affinity.languages.english.features;
    this.baseAppLang = Affinity.languages.english.application.timesheets;

    this.container = new Element('div', { 'class': 'ts-award-box', 'html': initHtml });
    this.userInfoBox = new Element('div', { 'class': 'ts-award-user-info' }).inject(this.container);
    this.awardBox = new Element('div', { 'class': 'ts-award-message hidden' }).inject(this.container);
    this.spinner = new Element('div', { 'class': 'ts-award-loader newloader hidden' }).inject(this.container);
    this.detailsBox = new Element('div', { 'class': 'ts-award-details-box section' }).inject(this.container);

    this.table = new Element('table', { 'class': 'ui-grid timesheet' }).inject(this.detailsBox);
    var thead = new Element('thead').inject(this.table);
    this.thead = new Element('tr').inject(thead);
    this.tbody = new Element('tbody').inject(this.table);
    var tfoot = new Element('tfoot').inject(this.table);
    this.tfoot = new Element('tr').inject(tfoot);

    this.spinner.innerHTML = '<svg class="spinner" width="65px" height="65px" viewBox="0 0 66 66" xmlns="http://www.w3.org/2000/svg"><circle class="circle" fill="none" stroke-width="6" stroke-linecap="round" cx="33" cy="33" r="30"></circle></svg>';

    this.loader = new Request.JSON({
      onSuccess: this._gotAwards
    });

    this.render();

    if(this.debug)
    {
      console.info('award modal trace (init):');
      console.trace();
    }
  },

  set: function (options)
  {
    if (!Affinity.isAwardsPopupEnabled()) return false;

    this.setOptions(options);

    this.render();
    
    if (this.debug)
    {
      console.info('award modal trace (set):');
      console.trace();
    }
  },

  render: function()
  {
    if (!Affinity.isAwardsPopupEnabled()) return false;

    this.thead.empty();
    this.tbody.empty();
    this.tfoot.empty();

    this.spinner.classList.remove('hidden');

    var userhtml = '', iconhtml = '';

    var date = false;
    try{ date = Date.parse(this._returnDateFromRow());} catch (ex) {}

    userhtml += '<span class="user">';
    userhtml += this._returnEmployeeNameFromRow(); // user name
    userhtml += '</span>  ';
    userhtml += '<span class="date">';
    if (date) userhtml += date.format('%a %e%o of %b, %Y'); '' // date
    userhtml += '</span>';
    
    this.options.iconData.forEach(function (msg) { iconhtml += msg.trim() + '<br />' });
    iconhtml += '<br />';

    this.awardBox.innerHTML = iconhtml;
    this.userInfoBox.innerHTML = userhtml;

    Affinity.uiModal.setClass('ui-new-modal');
    Affinity.uiModal.adopt(this.container);
    Affinity.uiModal.show();

    this._clearDragEvents();
    if (this.options.isDraggable && !Affinity.mobile)
    {
      Affinity.uiModal.modal.classList.add('draggable');
      Affinity.uiModal.modalbg.addClass('hidden');
      Affinity.uiModal.modal.addEventListener('mousedown', this._startDrag);
      Affinity.uiModal.afterClose = this._closed;
    }
    else
    {
      Affinity.uiModal.modal.classList.remove('draggable');
      Affinity.uiModal.modalbg.addClass('opaque');
    }

    if (!this.options.startPosition.x || !this.options.startPosition.y)
    {
      Affinity.uiModal.modal.classList.remove('positioned');
    }
    else
    {
      Affinity.uiModal.modal.classList.add('positioned');
    }

    this._setPosition();
    this._getAwards();

    this.isOpen = true;
  },

  close: function()
  {
    Affinity.uiModal.afterClose = this._closed;
    Affinity.uiModal.hide();
    this.isOpen = false;
  },

  /** privates **/

  _retuirnApiFromRow: function ()
  {
    var date = Date.parse(this.options.row.dataset.date),
      employee = this.options.row.dataset.employeeNo,
      timesheetId = this.options.row.dataset.timesheetId,
      api = '';
    api += Affinity.zelosroot + '?api=TimesheetPayTrans/GetPayTransForDate';
    api += '&fromDate=' + date.format('%d.%b.%Y');
    api += '&toDate=' + date.format('%d.%b.%Y');
    api += '&employeeNo=' + employee;
    api += '&view=daydetail';
    return api;
  },

  _returnEmployeeNoFromRow: function ()
  {
    return this.options.row.dataset.employeeNo || Affinity.login.profile.employeeNumber;
  },

  _returnEmployeeNameFromRow: function ()
  {
    return this.options.row.dataset.employeeName || Affinity.login.profile.commonName;
  },

  _returnDateFromRow: function ()
  {
    return this.options.row.dataset.date || false;
  },

  _isRowGood: function (rowData)
  {
    var isGood = false;
    var emp = this._returnEmployeeNoFromRow().toString().trim();
    rowData.Children.forEach(function (colData)
    {
      if (colData.Name && colData.Name.test(new RegExp('EmployeeNo', 'gi')))
      {
        if (colData.ValueAsString.toString().trim() === emp)
        {
          isGood = true;
          return isGood;
        }
      }
    }.bind(this));
    return isGood;
  },

  _gotAwards: function (jsonData)
  {
    var rows = [], firstRow = true, goodCount = 0, rowEl, dateCell, buttonCell, cellHidden;
    this.thead.empty();
    this.tbody.empty();
    this.tfoot.empty();
    if (jsonData.hasOwnProperty('Children') && jsonData.Children[0].Children[0].hasOwnProperty('Children'))
    {
      rows = jsonData.Children[0].Children[0].Children;
    }
    if (rows.length > 0)
    {
      rows.forEach(function (rowData)
      {
        if (this._isRowGood(rowData))
        {
          if(typeof this.options.returnRowMethod === 'function')
          {
            rowData.Attribute.IsReadOnly = true; // always force to read only
            rowEl = this.options.returnRowMethod(rowData, false, 'awards');
            dateCell = rowEl.querySelector('.col-id-TsDate');
            buttonCell = rowEl.querySelector('.col-id-RowButton');
            if (dateCell)
            {
              dateCell.classList.remove('active');
              dateCell.classList.add('hidden');
            }
            if (buttonCell)
            {
              buttonCell.classList.remove('active');
              buttonCell.classList.add('hidden');
            }
            this.tbody.adopt(rowEl);
            if (firstRow)
            {
              firstRow = false;
              rowData.Children.forEach(function (cellData)
              {
                cellHidden = cellData.Attribute.IsHidden || cellData.Name.test(new RegExp('TsDate|Button', 'gi')) ? true : false;
                this.thead.adopt(new Element('th', { 'class': cellHidden ? 'hidden' : 'active', 'html': cellData.Description.ShortText }));
              }.bind(this));
              this.tfoot.adopt(new Element('th', { 'colspan': rowEl.querySelectorAll('.active').length }));
            }

            goodCount++;

          }
        }
      }.bind(this));

      if (goodCount === 0)
      {
        this.tbody.adopt(new Element('tr').adopt(new Element('tr', { 'html': this.baseAppLang.features.awards.noawards })));
      }

      if (Affinity.tooltips) { Affinity.tooltips.processNew(); }
      if (Affinity.uiGrid) { Affinity.uiGrid.zebra(this.table, 'timesheet-row'); }
      if (Affinity.lookups) { Affinity.lookups.processNew({ jsonp: true }); }
      if (Affinity.displaylookups) { Affinity.displaylookups.processNew({ jsonp: true }); }

    }
    else
    {
      this.tbody.adopt(new Element('tr').adopt(new Element('tr', { 'html': this.baseAppLang.features.awards.noawards })));
    }

    this.spinner.classList.add('hidden');
    this._setPosition();
  },

  _getAwards: function ()
  {
    if (!Affinity.isAwardsPopupEnabled) return false;
    var api = this._retuirnApiFromRow();
    if (this.loader.isRunning()) this.loader.cancel();
    this.loader.url = api;
    this.loader.options.url = api;
    this.loader.get();
  },

  _setPosition: function ()
  {
    if (!isNaN(this.options.startPosition.x + this.options.startPosition.y))
    {
      var windowHeight = Math.max(document.documentElement.clientHeight, window.innerHeight || 0),
          modalHeight = this._getHeight(Affinity.uiModal.modal);

      if (this.options.startPosition.y + modalHeight > windowHeight)
      {
        Affinity.uiModal.modal.style.top = this.options.startPosition.y - 40 - modalHeight + 'px';
      }
      else
      {
        Affinity.uiModal.modal.style.top = this.options.startPosition.y + 'px';
      }
      Affinity.uiModal.modal.style.left = this.options.startPosition.x + 'px';
    }
    else
    {
      Affinity.uiModal.position();
    }
  },

  /* DRAG */

  _getHeight: function(node)
  {
    var bounds = node.getBoundingClientRect();
    return bounds.height;
  },

  _getMouseX: function(ev)
  {
    if (ev.pageX) return ev.pageX;
    if (ev.clientX) return ev.clientX + (document.documentElement.scrollLeft ? document.documentElement.scrollLeft : document.body.scrollLeft);
    return null;
  },

  _getMouseY: function (ev)
  {
    if (ev.pageY) return ev.pageY;
    if (ev.clientY) return ev.clientY + (document.documentElement.scrollTop ? document.documentElement.scrollTop : document.body.scrollTop);
    return null;
  },
  
  _offsetTop: false,
  _offsetLeft: false,
  _startDrag: function (ev)
  {
    this._clearDragEvents();
    this._offsetTop = this._getMouseY(ev);
    this._offsetLeft = this._getMouseX(ev);
    Affinity.uiModal.modal.classList.add('dragging');
    window.addEventListener('mousemove', this._drag);
    window.addEventListener('mouseup', this._stopDrag);
    ev.preventDefault();
    ev.stopPropagation();
  },
  
  _drag: function (ev)
  {
    var x = this._getMouseX(ev), y = this._getMouseY(ev), el = Affinity.uiModal.modal;
    if (x != this._offsetLeft || y != this._offsetTop)
    {
      el.style.top = (parseInt(el.style.top) + (y - this._offsetTop)) + 'px';
      el.style.left = (parseInt(el.style.left) + (x - this._offsetLeft)) + 'px';
      this._offsetTop = y;
      this._offsetLeft = x;
    }
  },
  
  _stopDrag: function (ev)
  {
    this._clearDragEvents();
    if (this.options.isDraggable && !Affinity.mobile)
    {
      Affinity.uiModal.modal.addEventListener('mousedown', this._startDrag);
    }
  },
  
  _clearDragEvents: function (ev)
  {
    Affinity.uiModal.modal.removeEventListener('mousedown', this._startDrag);
    Affinity.uiModal.modal.classList.remove('dragging');
    window.removeEventListener('mousemove', this._drag);
    window.removeEventListener('mouseup', this._stopDrag);
    this._offsetTop = false;
    this._offsetLeft = false;
  },

  /**/

  _closed: function ()
  {
    this._clearDragEvents();
    Affinity.uiModal.modal.classList.remove('positioned');
    Affinity.uiModal.modal.classList.remove('draggable');
  }

});;
