  /**/

  employeeSelect: false,
  getEmployeeList: function ()
  {
    if (!this.employeeSelect)
    {
      var url = Affinity.zelosroot + '?api=timesheetAsManager/getEmployees';
      new Request.JSONP({
        url: url,
        callbackKey: 'jsoncallback',
        method: 'get',
        noCache: true,
        onComplete: function (jsonData) {
          if (!JSON.Unauthorized(jsonData, 'bulk, getEmployeeList - ' + url))
          {
            log('&#x2714; attempted detailed toggleAddRowsForm "get employees" succeeded');

            this.employeeSelect = new Element('select');
            if (this.options.isEmployee)
            {
              this.employeeSelect.adopt(new Element('option', { 'html': Affinity.login.profile.commonName + ' (' + Affinity.login.profile.employeeNumber + ')', 'value': Affinity.login.profile.employeeNumber }));
            }
            Array.each(jsonData, function (pair)
            {
              if (pair.Value !== '' && pair.Key !== '' && pair.Key !== this.defaultEmployeeNumber)
              {
                this.employeeSelect.adopt(new Element('option', { 'html': pair.Value, 'value': pair.Key }));
              }
              else
              {
                this.employeeSelect.adopt(new Element('option', { 'html': 'Select Employee', 'value': '' }));
              }
            }.bind(this));

            this.gotEmployeeList();
          }
        }.bind(this),
        onError: function (error)
        {
          log('&#x2718; attempted detailed toggleAddRowsForm "get employees" failed with errors - ' + error);
        },
        onFailure: function (xhr, error)
        {
          log('&#x2718; attempted detailed toggleAddRowsForm "get employees" failed - ' + xhr.statusText);
        }
      }).send();
    }
    else
    {
      this.gotEmployeeList();
    }
  },

