  destroy: function ()
  {
    clearTimeout(this.switchTimer);
    clearTimeout(this.refreshOverviewTimer);
    clearTimeout(this.renderOverviewTimer);
    clearTimeout(this.employeSelectTimer);
    if (this.awardsLoader)
    {
      this.awardsLoader.removeEvents();
      this.awardsLoader.cancel();
    }
    if (this.detailsLoader)
    {
      this.detailsLoader.removeEvents();
      this.detailsLoader.cancel();
    }
    if (this.detailsZelosProcessor)
    {
      this.detailsZelosProcessor.removeEvents();
      this.detailsZelosProcessor.cancel();
    }
    if (this.awardsZelosProcessor)
    {
      this.awardsZelosProcessor.removeEvents();
      this.awardsZelosProcessor.cancel();
    }
    if (this.awardsWidget)
    {
      this.awardsWidget.removeEvents();
      this.awardsWidget.destroy();
    }
    if (this.overviewWidget)
    {
      this.overviewWidget.removeEvents();
      this.overviewWidget.destroy();
    }
    if (this.detailsWidget)
    {
      this.detailsWidget.removeEvents();
      this.detailsWidget.destroy();
    }
    if (this.doRibbon)
    {
      this.ribbon.destroy();
    }
    if (this.container)
    {
      if ('eliminate' in this.container)
      {
        this.container.eliminate('widget');
      }
      this.container.removeEvents();
      this.container.destroy();
    }
    this.removeEvents();
    window.removeEvent('gotUserWithPeriods', this.switchHandler);
    window.removeEvent('gotUser', this.switchHandler);
    Object.each(this, function (val, key) {
      this[key] = null;
      delete this[key];
    }.bind(this));
    Affinity.views.dualdetailed = null;
    delete Affinity.views.dualdetailed;
  }

